WITH exploded AS (SELECT id, effective_from, tier_value FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) x AS tier_value) SELECT CASE WHEN tier_value >= 87 THEN 'LARGE' ELSE 'SMALL' END AS tier_value_tier, ROUND(AVG(tier_value), 2) AS avg_tier_value, ROUND(AVG(tier_value), 2) AS avg_tier_value_2, MAX(tier_value) AS max_tier_value FROM exploded GROUP BY CASE WHEN tier_value >= 87 THEN 'LARGE' ELSE 'SMALL' END ORDER BY avg_tier_value DESC;
